rows=[[8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,8,8,5,8,8,8,8,8,5,8,8],[8,5,5,8,8,8,8,8,5,8,8,5,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8],[8,8,8,8,8,8,8,8,8,8,8,5,8,8,8,8,8,8,8,8,5,8,8,5,8,8,8]]
out=[r.copy() for r in rows]
# Fill gaps between 5s sharing a row or column; keep markers intact.
for r,row in enumerate(rows):
 xs=[c for c,v in enumerate(row) if v==5]
 for a,b in zip(xs,xs[1:]):
  for c in range(a+1,b): out[r][c]=3
for c in range(len(rows[0])):
 ys=[r for r in range(len(rows)) if rows[r][c]==5]
 for a,b in zip(ys,ys[1:]):
  for r in range(a+1,b): out[r][c]=3
assert all(len(r)==27 for r in out)
print(out)
